const merge = (a, b) => {
  for (const [k, v] of Object.entries(b)) {
    if (v && typeof v === 'object' && !Array.isArray(v)) a[k] = merge(a[k] && typeof a[k] === 'object' ? a[k] : {}, v);
    else a[k] = v;
  }
  return a;
};

for (const [locale, v] of Object.entries(T)) {
  const file = new URL(`../messages/${locale}.json`, import.meta.url);
  const json = JSON.parse(readFileSync(file, 'utf8'));
  merge(json, v);
  writeFileSync(file, JSON.stringify(json, null, 2) + '\n');
}
console.log('v4 strings added to', Object.keys(T).length, 'locales');
